def letter_case_permutation(s):
    results = [""]

    for c in s:
        if c.isalpha():
            next_results = []
            for r in results:
                next_results.append(r + c.lower())
                next_results.append(r + c.upper())
            results = next_results
        else:
            results = [r + c for r in results]

    return results


if __name__ == "__main__":
    print(letter_case_permutation("a1b2"))
    print(letter_case_permutation("3z4"))

