import java.util.*;

public class Main {
    static List<String> letterCasePermutation(String s) {
        List<String> results = new ArrayList<>();
        results.add("");

        for (char c : s.toCharArray()) {
            List<String> nextResults = new ArrayList<>();
            if (Character.isLetter(c)) {
                for (String r : results) {
                    nextResults.add(r + Character.toLowerCase(c));
                    nextResults.add(r + Character.toUpperCase(c));
                }
            } else {
                for (String r : results) {
                    nextResults.add(r + c);
                }
            }
            results = nextResults;
        }
        return results;
    }

    public static void main(String[] args) {
        System.out.println(letterCasePermutation("a1b2"));
        System.out.println(letterCasePermutation("3z4"));
    }
}

