void backtrack(int index) {
    if (index == (int)chars.size()) {
        result.push_back(chars);
        return;
    }
    if (isalpha(chars[index])) {
        chars[index] = tolower(chars[index]);
        backtrack(index + 1);
        chars[index] = toupper(chars[index]);
        backtrack(index + 1);
    } else {
        backtrack(index + 1);
    }
}

vector<string> letterCasePermutation(string s) {
    result.clear();
    chars = s;
    backtrack(0);
    return result;
}

